from cache import make_key
from service import score


def test_key_is_tuple_of_all_inputs():
    assert make_key("ab", 1, 2) == ("ab", 1, 2)
    assert make_key(None, "p", None) == (None, "p", None)


def test_ambiguous_concatenation_keys_differ():
    # Old-style ambiguous key: "a"+1+2 vs "ab"+1+1 would collide; tuples must not.
    assert make_key("a", 1, 2) != make_key("ab", 1, 1)
    assert make_key("a", 2, 2) != make_key("ab", 1, 1)


def test_same_inputs_reuse_cached_value():
    store = {}
    s1 = score(store, "job", 1, 2, lambda: "v1")
    assert store == {("job", 1, 2): "v1"}
    assert score(store, "job", 1, 2, lambda: "v9") == "v1"


def test_none_inputs_reuse_cached_value():
    store = {}
    s1 = score(store, "job", None, None, lambda: "none_v1")
    assert store == {("job", None, None): "none_v1"}
    assert score(store, "job", None, None, lambda: "none_v2") == "none_v1"


def test_change_compute_recomputes():
    store = {}
    s1 = score(store, "job", 1, 2, lambda: "v1")
    assert score(store, "job", 1, 2, lambda: "v2") == "v2"
    assert store == {("job", 1, 2): "v2"}


def test_change_job_text_recomputes():
    store = {}
    score(store, "job", 1, 2, lambda: "a")
    assert score(store, "job2", 1, 2, lambda: "b") == "b"


def test_change_profile_version_recomputes():
    store = {}
    score(store, "job", 1, 2, lambda: "a")
    assert score(store, "job", 2, 2, lambda: "b") == "b"


def test_change_criteria_version_recomputes():
    store = {}
    score(store, "job", 1, 2, lambda: "a")
    assert score(store, "job", 1, 3, lambda: "b") == "b"


def test_mixed_none_vs_value_distinct_keys():
    store = {}
    score(store, "job", None, None, lambda: "none")
    score(store, "job", 1, None, lambda: "pv")
    assert score(store, "job", None, None, lambda: "none") == "none"
    assert score(store, "job", 1, None, lambda: "pv") == "pv"
    assert store == {
        ("job", None, None): "none",
        ("job", 1, None): "pv",
    }
